INSERT INTO "contacts" ("id", "full_name", "company_name", "email", "phone", "subject", "message", "status", "assigned_to", "admin_note", "resolved_at", "created_at", "updated_at") VALUES ('f0000002-0000-4000-8000-000000000002', 'Trần Thị Thu Trang', 'Phòng Thử nghiệm Quatest 2', 'trang.tt@quatest2.gov.vn', '0983 678 910', 'Tư vấn bổ sung phụ kiện cho thiết bị PAC OptiDist 2', 'Chào đội ngũ kỹ thuật, chúng tôi cần mua bổ sung bình hứng và nhiệt kế chuẩn cho máy OptiDist 2 vừa bàn giao. Nhờ quý công ty gửi danh mục phụ tùng chính hãng.', 'processing', '22222222-2222-4222-8222-222222222222', 'Đang liên hệ đại diện PAC Singapore để xác nhận mã linh kiện.', NULL, '2026-09-14T14:20:00.000Z'::timestamptz, '2026-09-23T11:37:15.924Z'::timestamptz);
INSERT INTO "contacts" ("id", "full_name", "company_name", "email", "phone", "subject", "message", "status", "assigned_to", "admin_note", "resolved_at", "created_at", "updated_at") VALUES ('f0000003-0000-4000-8000-000000000003', 'Lê Hoàng Nam', 'Tổng Công ty Khí Việt Nam (PV Gas)', 'nam.lh@pvgas.com.vn', '0903 112 233', 'Tư vấn van điều khiển Masoneilan 21000 cho hệ thống khí khô', 'Chúng tôi muốn tìm hiểu thông số kỹ thuật và điều kiện làm việc của van điều khiển Masoneilan Class 600 cho dự án nâng công suất trạm phân phối khí.', 'resolved', '11111111-1111-4111-8111-111111111111', 'Đã gửi catalog kỹ thuật và tài liệu sizing van Masoneilan ngày 16/09.', '2026-09-16T16:00:00.000Z'::timestamptz, '2026-09-12T10:15:00.000Z'::timestamptz, '2026-09-23T11:37:15.924Z'::timestamptz);
