INSERT INTO "contacts" ("id", "full_name", "company_name", "email", "phone", "subject", "message", "status", "assigned_to", "admin_note", "resolved_at", "created_at", "updated_at") VALUES ('f0000001-0000-4000-8000-000000000001', 'Nguyễn Văn Hải', 'Công ty Cổ phần Lọc hóa dầu Bình Sơn (BSR)', 'hai.nv@bsr.com.vn', '0912 345 678', 'Yêu cầu báo giá bảo trì định kỳ van an toàn Consolidated', 'Kính gửi LT Việt Nam, chúng tôi đang chuẩn bị kế hoạch bảo dưỡng định kỳ cho phân xưởng chưng cất tháp dầu thô. Xin vui lòng gửi phương án kiểm định van an toàn tại hiện trường bằng thiết bị EVT-Pro.', 'processing', '11111111-1111-4111-8111-111111111111', 'Đã chuyển phòng kỹ thuật van chuẩn bị tài liệu báo giá.', NULL, '2026-09-15T09:30:00.000Z'::timestamptz, '2026-09-24T17:03:08.284Z'::timestamptz);
