INSERT INTO "news_events" ("id", "type", "title", "slug", "short_description", "thumbnail_image_id", "content", "status", "published_at", "event_start_at", "event_end_at", "location", "author_id", "created_at", "updated_at", "deleted_at") VALUES ('e0000000-0000-4000-8000-000000000001', 'news', 'LT Việt Nam hoàn thành lắp đặt và bàn giao PAC OptiDist 2 tại Quatest 2', 'ban-giao-pac-optidist-2', 'Đội ngũ kỹ thuật hoàn thành lắp đặt, hướng dẫn vận hành và chuyển giao thiết bị chưng cất tự động.', 'a0000000-0000-4000-8000-00000000000e', '{"blocks":[{"data":{"text":"LT Việt Nam hoàn thành lắp đặt và bàn giao PAC OptiDist 2 tại Quatest 2","level":2},"type":"heading"},{"data":{"text":"Dự án tập trung vào việc đưa hệ thống chưng cất tự động vào vận hành ổn định tại phòng thí nghiệm của khách hàng."},"type":"paragraph"},{"data":{"text":"Phạm vi thực hiện gồm lắp đặt thiết bị, kiểm tra điều kiện vận hành, chạy thử và hướng dẫn người sử dụng."},"type":"paragraph"},{"data":{"text":"Hồ sơ kỹ thuật và hướng dẫn vận hành được tập hợp để người sử dụng thuận tiện tra cứu sau bàn giao."},"type":"paragraph"}],"version":1}'::jsonb, 'published', '2026-06-01T08:00:00.000Z'::timestamptz, NULL, NULL, NULL, '11111111-1111-4111-8111-111111111111', '2026-09-23T11:37:15.819Z'::timestamptz, '2026-09-23T11:37:15.819Z'::timestamptz, NULL);
INSERT INTO "news_events" ("id", "type", "title", "slug", "short_description", "thumbnail_image_id", "content", "status", "published_at", "event_start_at", "event_end_at", "location", "author_id", "created_at", "updated_at", "deleted_at") VALUES ('e0000000-0000-4000-8000-000000000002', 'event', 'LT Việt Nam phối hợp tổ chức hội thảo bảo dưỡng và kiểm định van an toàn', 'hoi-thao-van-an-toan', 'Hội thảo được tổ chức tại Hà Nội cùng Bộ Công Thương và Baker Hughes GE, với đại biểu từ hơn 20 nhà máy công nghiệp.', 'a0000000-0000-4000-8000-00000000000f', '{"blocks":[{"data":{"text":"LT Việt Nam phối hợp tổ chức hội thảo bảo dưỡng và kiểm định van an toàn","level":2},"type":"heading"},{"data":{"text":"Cuối năm 2019 tại Hà Nội, Bộ Công Thương, LT Việt Nam và Baker Hughes GE phối hợp tổ chức hội thảo về bảo dưỡng và kiểm định van an toàn trong nhà máy công nghiệp."},"type":"paragraph"},{"data":{"text":"Hội thảo do lãnh đạo Cục An toàn và Môi trường Công nghiệp chủ trì, với đại biểu đến từ hơn 20 nhà máy lọc dầu, nhiệt điện, phân bón và công nghiệp lớn."},"type":"paragraph"},{"data":{"text":"Các chuyên gia trình bày quy trình bảo dưỡng, sửa chữa và kiểm định van an toàn, đồng thời trao đổi kinh nghiệm vận hành trong những điều kiện làm việc khắc nghiệt."},"type":"paragraph"},{"data":{"text":"Tìm hiểu giải pháp van an toàn cho nhà máy — Xem danh mục van an toàn Consolidated và các thiết bị hỗ trợ vận hành hiện có trên website.","author":"Xem giải pháp van Baker Hughes"},"type":"quote"}],"version":1}'::jsonb, 'published', '2019-06-01T08:00:00.000Z'::timestamptz, '2019-11-20T08:30:00.000Z'::timestamptz, '2019-11-20T17:00:00.000Z'::timestamptz, 'Khách sạn Melia, 44 Lý Thường Kiệt, Hoàn Kiếm, Hà Nội', '11111111-1111-4111-8111-111111111111', '2026-09-23T11:37:15.819Z'::timestamptz, '2026-09-23T11:37:15.819Z'::timestamptz, NULL);
INSERT INTO "news_events" ("id", "type", "title", "slug", "short_description", "thumbnail_image_id", "content", "status", "published_at", "event_start_at", "event_end_at", "location", "author_id", "created_at", "updated_at", "deleted_at") VALUES ('e0000000-0000-4000-8000-000000000003', 'news', 'Chuyển giao thiết bị xác định điểm đông đặc Phase Technology 70Xi tại Skypec', 'chuyen-giao-dfa-70xi', 'LT Việt Nam hoàn thành giao hàng, lắp đặt, chạy thử và đào tạo chuyển giao công nghệ tại chi nhánh Skypec Hà Nội.', 'a0000000-0000-4000-8000-000000000010', '{"blocks":[{"data":{"text":"Chuyển giao thiết bị xác định điểm đông đặc Phase Technology 70Xi tại Skypec","level":2},"type":"heading"},{"data":{"text":"Trong hai ngày 7 và 8 tháng 7 năm 2025, đội ngũ LT Việt Nam triển khai thiết bị phân tích điểm đông đặc Phase Technology tại chi nhánh Hà Nội của Công ty Cổ phần Nhiên liệu bay Petrolimex (Skypec)."},"type":"paragraph"},{"data":{"text":"Phạm vi công việc gồm lắp đặt tại hiện trường, tích hợp, hiệu chuẩn, chạy thử và xác nhận khả năng hoạt động của thiết bị."},"type":"paragraph"},{"data":{"text":"Chương trình chuyển giao bao gồm đào tạo lý thuyết và thực hành, hướng dẫn bảo trì, xử lý sự cố và bàn giao tài liệu kỹ thuật cùng hướng dẫn sử dụng."},"type":"paragraph"},{"data":{"text":"Bạn đang cần thiết bị xác định điểm đông đặc? — Chia sẻ loại mẫu, phương pháp hoặc tiêu chuẩn áp dụng để đội ngũ kỹ thuật tiếp nhận đúng nhu cầu.","author":"Trao đổi về ứng dụng này"},"type":"quote"}],"version":1}'::jsonb, 'published', '2025-06-01T08:00:00.000Z'::timestamptz, NULL, NULL, NULL, '11111111-1111-4111-8111-111111111111', '2026-09-23T11:37:15.819Z'::timestamptz, '2026-09-23T11:37:15.819Z'::timestamptz, NULL);
INSERT INTO "standards" ("id", "code", "organization", "year", "title", "description", "created_at", "updated_at") VALUES ('b0000000-0000-4000-8000-000000000001', 'ASTM D86', 'ASTM', 2023, 'Standard Test Method for Distillation of Petroleum Products and Liquid Fuels at Atmospheric Pressure', 'Xác định khoảng chưng cất của các sản phẩm dầu mỏ ở áp suất khí quyển.', '2026-09-23T11:37:14.918Z'::timestamptz, '2026-09-23T11:37:14.918Z'::timestamptz);
INSERT INTO "standards" ("id", "code", "organization", "year", "title", "description", "created_at", "updated_at") VALUES ('b0000000-0000-4000-8000-000000000002', 'ISO 3405', 'ISO', 2019, 'Petroleum and related products — Determination of distillation characteristics at atmospheric pressure', 'Tiêu chuẩn quốc tế xác định đặc tính chưng cất ở áp suất khí quyển.', '2026-09-23T11:37:14.918Z'::timestamptz, '2026-09-23T11:37:14.918Z'::timestamptz);
INSERT INTO "standards" ("id", "code", "organization", "year", "title", "description", "created_at", "updated_at") VALUES ('b0000000-0000-4000-8000-000000000003', 'IP 123', 'Energy Institute', 2019, 'Petroleum products — Determination of distillation characteristics at atmospheric pressure', 'Phương pháp kiểm nghiệm chưng cất khí quyển theo tiêu chuẩn Viện Năng lượng Anh Quốc.', '2026-09-23T11:37:14.918Z'::timestamptz, '2026-09-23T11:37:14.918Z'::timestamptz);
INSERT INTO "standards" ("id", "code", "organization", "year", "title", "description", "created_at", "updated_at") VALUES ('b0000000-0000-4000-8000-000000000004', 'ASTM D7668', 'ASTM', 2022, 'Standard Test Method for Determination of Derived Cetane Number (DCN) of Diesel Fuel Oils', 'Xác định trị số cetane dẫn xuất (DCN) của diesel bằng buồng đốt thể tích không đổi.', '2026-09-23T11:37:14.918Z'::timestamptz, '2026-09-23T11:37:14.918Z'::timestamptz);
INSERT INTO "standards" ("id", "code", "organization", "year", "title", "description", "created_at", "updated_at") VALUES ('b0000000-0000-4000-8000-000000000005', 'ASTM D445', 'ASTM', 2021, 'Standard Test Method for Kinematic Viscosity of Transparent and Opaque Liquids', 'Đo độ nhớt động học của chất lỏng trong suốt và mờ đục.', '2026-09-23T11:37:14.918Z'::timestamptz, '2026-09-23T11:37:14.918Z'::timestamptz);
INSERT INTO "standards" ("id", "code", "organization", "year", "title", "description", "created_at", "updated_at") VALUES ('b0000000-0000-4000-8000-000000000006', 'ISO 3104', 'ISO', 2020, 'Petroleum products — Transparent and opaque liquids — Determination of kinematic viscosity', 'Tiêu chuẩn ISO xác định độ nhớt động học và tính toán độ nhớt động lực học.', '2026-09-23T11:37:14.918Z'::timestamptz, '2026-09-23T11:37:14.918Z'::timestamptz);
INSERT INTO "standards" ("id", "code", "organization", "year", "title", "description", "created_at", "updated_at") VALUES ('b0000000-0000-4000-8000-000000000007', 'ASTM D93', 'ASTM', 2020, 'Standard Test Methods for Flash Point by Pensky-Martens Closed Cup Tester', 'Xác định điểm chớp cháy bằng thiết bị cốc kín Pensky-Martens.', '2026-09-23T11:37:14.918Z'::timestamptz, '2026-09-23T11:37:14.918Z'::timestamptz);
INSERT INTO "standards" ("id", "code", "organization", "year", "title", "description", "created_at", "updated_at") VALUES ('b0000000-0000-4000-8000-000000000008', 'ISO 2719', 'ISO', 2016, 'Determination of flash point — Pensky-Martens closed cup method', 'Xác định điểm chớp cháy theo phương pháp cốc kín Pensky-Martens.', '2026-09-23T11:37:14.918Z'::timestamptz, '2026-09-23T11:37:14.918Z'::timestamptz);
INSERT INTO "standards" ("id", "code", "organization", "year", "title", "description", "created_at", "updated_at") VALUES ('b0000000-0000-4000-8000-000000000009', 'ASTM D1160', 'ASTM', 2018, 'Standard Test Method for Distillation of Petroleum Products at Reduced Pressure', 'Chưng cất sản phẩm dầu mỏ ở áp suất chân không giảm thấp.', '2026-09-23T11:37:14.918Z'::timestamptz, '2026-09-23T11:37:14.918Z'::timestamptz);
INSERT INTO "standards" ("id", "code", "organization", "year", "title", "description", "created_at", "updated_at") VALUES ('b0000000-0000-4000-8000-00000000000a', 'ISO 6616', 'ISO', 2000, 'Petroleum products — Determination of distillation characteristics at reduced pressure', 'Xác định đặc tính chưng cất chân không của các phân đoạn dầu nặng.', '2026-09-23T11:37:14.918Z'::timestamptz, '2026-09-23T11:37:14.918Z'::timestamptz);
INSERT INTO "standards" ("id", "code", "organization", "year", "title", "description", "created_at", "updated_at") VALUES ('b0000000-0000-4000-8000-00000000000b', 'ASTM D5191', 'ASTM', 2022, 'Standard Test Method for Vapor Pressure of Petroleum Products and Liquid Fuels (Mini Method)', 'Đo áp suất hơi vi lượng của xăng và nhiên liệu lỏng.', '2026-09-23T11:37:14.918Z'::timestamptz, '2026-09-23T11:37:14.918Z'::timestamptz);
